import os,json,subprocess
from pathlib import Path
root=Path("/srv/projects/telegram-robot-leads")
old=Path("/root/.pm2")
alias=Path("/opt/telegram-robot-leads")
out={"global":{},"files":[],"classes":{},"process_references":[],"telegram_alias":{},"other":{}}
def cmd(args,t=12):
 return subprocess.run(args,capture_output=True,text=True,timeout=t)
out["global"]["real"]=old.is_dir() and not old.is_symlink()
out["global"]["old_service_active"]=cmd(["systemctl","is-active","pm2-root"]).stdout.strip()
out["global"]["old_service_enabled"]=cmd(["systemctl","is-enabled","pm2-root"]).stdout.strip()
out["global"]["new_service_active"]=cmd(["systemctl","is-active","pm2-telegram-robot-leads"]).stdout.strip()
out["global"]["new_service_enabled"]=cmd(["systemctl","is-enabled","pm2-telegram-robot-leads"]).stdout.strip()
if old.is_dir():
 for cur,dirs,files in os.walk(old,followlinks=False):
  depth=len(Path(cur).relative_to(old).parts)
  if depth>2:dirs[:]=[];continue
  for n in dirs+files:
   p=Path(cur)/n
   try:
    rel=p.relative_to(old).as_posix()
    st=p.lstat()
    klass="iptvpn" if "iptvpn" in n.lower() else "telegram" if "telegram" in n.lower() else "shared"
    x={"rel":rel,"type":"symlink" if p.is_symlink() else "dir" if p.is_dir() else "file","bytes":st.st_size if p.is_file() else 0,"owner":st.st_uid,"class":klass}
    out["files"].append(x)
    out["classes"][klass]=out["classes"].get(klass,0)+1
   except OSError:pass
out["telegram_alias"]={"link":alias.is_symlink(),"correct_target":alias.is_symlink() and alias.resolve(strict=False)==root,"source_references":[]}
lookups=("/etc/systemd/system","/etc/nginx","/etc/cron.d","/usr/local/bin","/usr/local/sbin",str(root))
checked=0
for base in lookups:
 p=Path(base)
 if not p.is_dir():continue
 for cur,dirs,files in os.walk(p,followlinks=False):
  if len(Path(cur).relative_to(p).parts)>4:dirs[:]=[];continue
  dirs[:]=[x for x in dirs if x not in (".git","archive","private","data",".venv",".pm2","node_modules","logs","__pycache__","tools")]
  for n in files:
   f=Path(cur)/n
   try:
    if not f.is_file() or f.is_symlink() or f.stat().st_size>110000:continue
    checked+=1
    b=f.read_bytes()
    if b"/opt/telegram-robot-leads" in b:out["telegram_alias"]["source_references"].append(str(f))
   except OSError:pass
out["telegram_alias"]["scanned"]=checked
for p in Path("/proc").iterdir():
 if not p.name.isdigit() or int(p.name) in (os.getpid(),os.getppid()):continue
 try:
  if (p/"comm").read_text().strip() in ("bash","python","python3","node","PM2","pm2"):
   en=(p/"environ").read_bytes();cl=(p/"cmdline").read_bytes();cwd=os.readlink(str(p/"cwd"))
   if b"/root/.pm2" in cl or b"/root/.pm2" in en or cwd.startswith("/root/.pm2"):out["process_references"].append({"pid":int(p.name),"comm":(p/"comm").read_text().strip(),"kind":"old_pm2"})
   if b"/opt/telegram-robot-leads" in cl or b"/opt/telegram-robot-leads" in en or cwd.startswith("/opt/telegram-robot-leads"):out["process_references"].append({"pid":int(p.name),"comm":(p/"comm").read_text().strip(),"kind":"old_telegram_alias"})
 except OSError:pass
print(json.dumps(out,sort_keys=True))
